(function(){
'use strict';

const STORAGE_KEY='voresCamping.v12';
const APP_VERSION=12;
const $=(sel,root=document)=>root.querySelector(sel);
const $$=(sel,root=document)=>[...root.querySelectorAll(sel)];
const app=$('#app');
const ui={visitedSearch:'',visitedSort:'latest',wishSearch:'',wishSort:'planned',mapFilter:'all',mapResults:[],mapStoredSearch:'',editingImages:[],routeDraft:null,settingsTab:'general'};
let data;
let countdownTimer;

const DEFAULT_CATEGORIES=[
  {id:'location',name:'Beliggenhed',icon:'map-pin'},
  {id:'value',name:'Pris & kvalitet',icon:'badge-dollar-sign'},
  {id:'cleanliness',name:'Renlighed',icon:'sparkles'},
  {id:'service',name:'Service',icon:'bell'},
  {id:'facilities',name:'Faciliteter',icon:'shower-head'},
  {id:'dog',name:'Hundevenlig',icon:'paw-print'},
  {id:'cycling',name:'Cykelmuligheder',icon:'bike'}
];

function uid(prefix='id'){return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;}
function isoDate(date=new Date()){return new Date(date).toISOString().slice(0,10);}
function esc(value=''){return String(value).replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));}
function nl2br(value=''){return esc(value).replace(/\n/g,'<br>');}
function num(value,fallback=0){const n=Number(String(value??'').replace(',','.'));return Number.isFinite(n)?n:fallback;}
function clamp(n,min,max){return Math.min(max,Math.max(min,n));}
function formatDate(value,opts={day:'numeric',month:'short',year:'numeric'}){if(!value)return 'Ikke angivet';const d=new Date(`${String(value).slice(0,10)}T12:00:00`);return Number.isNaN(d.getTime())?String(value):new Intl.DateTimeFormat('da-DK',opts).format(d);}
function formatKm(m){return `${(Number(m||0)/1000).toLocaleString('da-DK',{maximumFractionDigits:1})} km`;}
function formatDuration(seconds){const min=Math.round(Number(seconds||0)/60);if(min<60)return `${min} min`;return `${Math.floor(min/60)} t ${min%60} min`;}
function stars(rating=0){const r=clamp(Math.round(num(rating)),0,5);return `<span class="stars" aria-label="${num(rating).toFixed(1)} ud af 5">${'★'.repeat(r)}${'☆'.repeat(5-r)}</span>`;}
function icon(name){return `<i data-lucide="${esc(name)}"></i>`;}
function firstImage(place){return place?.images?.[0]||'assets/hero-camping.jpg';}
function latestDate(place){return [...(place.visitDates||[])].sort().at(-1)||'';}
function averageRating(place){const values=Object.values(place.ratings||{}).map(Number).filter(v=>v>0);return values.length?values.reduce((a,b)=>a+b,0)/values.length:0;}
function applyDerived(){data.places.forEach(p=>p.averageRating=averageRating(p));}
function visitCount(){return data.places.filter(p=>p.status==='visited').length;}
function wishCount(){return data.places.filter(p=>p.status==='wishlist').length;}
function countriesCount(){return new Set(data.places.filter(p=>p.status==='visited'&&p.country).map(p=>p.country.trim().toLowerCase())).size;}
function routesCount(){return data.places.reduce((sum,p)=>sum+(p.routes?.length||0),0);}
function getPlace(id){return data.places.find(p=>String(p.id)===String(id));}
function allRoutes(){return data.places.flatMap(place=>(place.routes||[]).map(route=>({...route,placeId:place.id,placeName:place.name})));}

function defaultData(){
 const visited=[
  ['Lystbækgård Camping','Thyholm','Danmark',56.632,8.535,'assets/camp-1.jpg',['Natur','Ved vandet','Hundevenlig'],'2026-07-12',{location:5,value:5,cleanliness:5,service:5,facilities:4.8,dog:5,cycling:4.8}],
  ['Moselcamping Cochem','Cochem','Tyskland',50.146,7.166,'assets/camp-2.jpg',['Ved flod','Cykelruter','Tæt på byen'],'2026-05-03',{location:5,value:4.8,cleanliness:5,service:4.7,facilities:4.8,dog:4.6,cycling:5}],
  ['Camping Bella Austria','Millstatt','Østrig',46.804,13.58,'assets/camp-3.jpg',['Bjerge','Natur','Cykelruter'],'2026-04-18',{location:5,value:4.6,cleanliness:4.8,service:4.7,facilities:4.5,dog:4.4,cycling:4.8}],
  ['Århus Camping','Århus','Danmark',56.206,10.154,'assets/camp-4.jpg',['By tæt på','Hundevenlig','Cykelruter'],'2026-04-20',{location:4.5,value:4.6,cleanliness:4.7,service:4.6,facilities:4.5,dog:4.8,cycling:5}],
  ['Camping de la Plage','Bretagne','Frankrig',48.335,-4.5,'assets/camp-5.jpg',['Ved havet','Natur','Familievenlig'],'2026-03-15',{location:4.9,value:4.4,cleanliness:4.5,service:4.4,facilities:4.4,dog:4.5,cycling:4.5}],
  ['Camping Park Umag','Umag','Kroatien',45.366,13.534,'assets/camp-6.jpg',['Ved vandet','Cykelruter','Familievenlig'],'2026-03-07',{location:4.7,value:4.3,cleanliness:4.5,service:4.8,facilities:4.6,dog:4.5,cycling:4.7}]
 ].map((x,i)=>({id:`demo-v-${i+1}`,status:'visited',name:x[0],address:'',postalCode:'',city:x[1],region:'',country:x[2],website:'',phone:'',coords:{lat:x[3],lng:x[4]},visitDates:[x[7]],plannedDate:'',description:i===0?'Rolig og hyggelig campingplads med skøn natur og god plads til både mennesker og hund.':'En dejlig campingoplevelse, som fortjener en plads i vores personlige rejsebog.',notes:'',tags:x[6],ratings:x[8],images:[x[5]],sights:[],routes:[],favorite:i<2,createdAt:'2026-01-01T10:00:00Z',updatedAt:new Date().toISOString()}));
 visited[0].sights=[{id:uid('sight'),name:'Oddesundbroen',description:'Flot udsigt og en god lille udflugt.',link:''}];
 visited[1].routes=[{id:'route-cochem',name:'Moselstien langs floden',start:'Moselcamping Cochem',end:'Beilstein',waypoints:[],difficulty:'Let',description:'Rolig cykeltur langs Mosel med udsigt til vinmarker.',distance:28600,duration:7200,coordinates:[[7.166,50.146],[7.13,50.12],[7.08,50.105],[7.05,50.106]],googleMapsLink:''}];
 visited[3].routes=[{id:'route-aarhus',name:'Stien Århus rundt',start:'Århus Camping',end:'Aarhus Ø',waypoints:[],difficulty:'Let',description:'By, havn og grønne områder i én samlet tur.',distance:44000,duration:9900,coordinates:[[10.154,56.206],[10.18,56.17],[10.22,56.16]],googleMapsLink:''}];
 const wishes=[
  ['Camping Jungfrau','Interlaken','Schweiz',46.594,7.909,'assets/wish-1.jpg',['Bjerge','Natur','Søudsigt','Helårsåben'],'2026-09-01','Skøn beliggenhed med fantastisk udsigt til bjergene.'],
  ['Campingplatz Seeblick','Salzkammergut','Østrig',47.7,13.55,'assets/wish-2.jpg',['Ved sø','Natur','Hundevenlig'],'2026-10-01','Rolig plads direkte ved søen – perfekt til efterårsture.'],
  ['Camping Le Paradis','Carnac-en-Rouillon','Frankrig',47.585,-3.079,'assets/wish-3.jpg',['Ved havet','Familievenlig','Cykelruter'],'2027-07-01','Tæt på stranden og hyggelige markeder i området.'],
  ['Nordkap Camping','Nordkapp','Norge',71.169,25.783,'assets/wish-4.jpg',['Natur','Eventyr','Cykelruter','Helårsåben'],'2027-06-15','Drømmen om Nordkap – en tur mod midnatssolen.']
 ].map((x,i)=>({id:`demo-w-${i+1}`,status:'wishlist',name:x[0],address:'',postalCode:'',city:x[1],region:'',country:x[2],website:'',phone:'',coords:{lat:x[3],lng:x[4]},visitDates:[],plannedDate:x[7],description:x[8],notes:'',tags:x[6],ratings:{},images:[x[5]],sights:[],routes:[],favorite:i===0,createdAt:'2026-01-01T10:00:00Z',updatedAt:new Date().toISOString()}));
 return {
  version:APP_VERSION,
  settings:{
   appName:'Vores Camping',subtitle:'Vores ture, vores minder',names:'Sisi & Jan',greetingText:'Her er jeres camping-overblik',nextTrip:{title:'Norge 2026',date:'2026-09-15'},showCountdown:true,coverImage:'assets/cover.jpg',countdownImage:'assets/sisi-countdown.jpg',scale:1,density:'compact',theme:'light',accent:'#1f3d2e',mapStyle:'liberty',mapProvider:'maplibre',orsKey:'',googleMapsKey:'',sections:['latest','top','wishlist','routes','sisi'],hiddenSections:[]
  },
  ratingCategories:structuredClone(DEFAULT_CATEGORIES),places:[...visited,...wishes],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()
 };
}

function migrate(raw){
 try{
  if(Array.isArray(raw)) raw={places:raw};
  const base=defaultData();
  const out={...base,...raw,settings:{...base.settings,...(raw?.settings||{})}};
  out.places=Array.isArray(raw?.places)?raw.places:base.places;
  out.ratingCategories=Array.isArray(raw?.ratingCategories)&&raw.ratingCategories.length?raw.ratingCategories:structuredClone(DEFAULT_CATEGORIES);
  out.places=out.places.map((p,i)=>({
   id:p.id||uid('camp'),status:p.status==='wishlist'||p.wish===true?'wishlist':'visited',name:p.name||p.title||`Campingplads ${i+1}`,address:p.address||'',postalCode:p.postalCode||p.zip||'',city:p.city||'',region:p.region||'',country:p.country||'',website:p.website||'',phone:p.phone||'',coords:{lat:num(p.coords?.lat??p.lat,NaN),lng:num(p.coords?.lng??p.lng??p.lon,NaN)},visitDates:Array.isArray(p.visitDates)?p.visitDates:(p.visitDate?[p.visitDate]:[]),plannedDate:p.plannedDate||'',description:p.description||'',notes:p.notes||'',tags:Array.isArray(p.tags)?p.tags:[],ratings:p.ratings&&typeof p.ratings==='object'?p.ratings:{},images:Array.isArray(p.images)&&p.images.length?p.images:[],sights:Array.isArray(p.sights)?p.sights:[],routes:Array.isArray(p.routes)?p.routes:[],favorite:Boolean(p.favorite),createdAt:p.createdAt||new Date().toISOString(),updatedAt:p.updatedAt||new Date().toISOString()
  }));
  out.version=APP_VERSION;return out;
 }catch(err){console.error('Migrering fejlede',err);return defaultData();}
}

function loadData(){
 const keys=[STORAGE_KEY,'voresCampingData','vores-camping','voresCamping.v11','campingData'];
 for(const key of keys){
  try{const raw=localStorage.getItem(key);if(raw){const parsed=JSON.parse(raw);const migrated=migrate(parsed);if(key!==STORAGE_KEY)localStorage.setItem(STORAGE_KEY,JSON.stringify(migrated));return migrated;}}catch(err){console.warn(`Kunne ikke læse ${key}`,err);}
 }
 return defaultData();
}

function saveData(message){
 data.updatedAt=new Date().toISOString();applyDerived();
 try{localStorage.setItem(STORAGE_KEY,JSON.stringify(data));if(message)toast(message,'success');}
 catch(err){console.error(err);toast('Browserens lager er fyldt. Eksportér en backup og fjern nogle billeder.','error');}
 updateShell();
}

function applySettings(){
 const s=data.settings;
 document.documentElement.style.setProperty('--scale',String(clamp(num(s.scale,1),.8,1.25)));
 document.documentElement.style.setProperty('--forest',s.accent||'#1f3d2e');
 document.body.classList.toggle('density-airy',s.density==='airy');
 document.body.classList.toggle('theme-dark',s.theme==='dark');
 document.querySelector('meta[name="theme-color"]')?.setAttribute('content',s.accent||'#1f3d2e');
 document.title=s.appName||'Vores Camping';
}

function greeting(){const h=new Date().getHours();return h<10?'Godmorgen':h<17?'Goddag':'Godaften';}
function updateShell(){
 applySettings();
 const s=data.settings;
 $('#profileGreeting').textContent=greeting();$('#profileNames').textContent=s.names||'Sisi & Jan';
 $('#mobileAppName').textContent=s.appName||'Vores Camping';$('#mobileSubtitle').textContent=s.subtitle||'';
 const count=$('#sidebarCountdown');if(count)count.innerHTML=renderCountdownMini();
}

function parseRoute(){const raw=(location.hash||'#/overblik').replace(/^#\/?/,'');const [pathQuery,...rest]=raw.split('/');const [path,q]=pathQuery.split('?');return {path:path||'overblik',segments:[path,...rest],query:new URLSearchParams(q||'')};}
function setActiveNav(path){const normalized={campingplads:'besoegte',rediger:'besoegte',tilfoej:'besoegte',rute:'besoegte','rute-editor':'besoegte',vurderingskategorier:'indstillinger',backup:'indstillinger'}[path]||path;$$('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===normalized));}
function refreshIcons(){try{window.lucide?.createIcons({attrs:{'aria-hidden':'true'}});}catch(_e){}}
function toast(message,type='success'){const root=$('#toastRoot');const el=document.createElement('div');el.className=`toast ${type==='error'?'error':type==='warn'?'warn':''}`;el.innerHTML=`${icon(type==='error'?'circle-alert':type==='warn'?'triangle-alert':'circle-check')}<span>${esc(message)}</span>`;root.appendChild(el);refreshIcons();setTimeout(()=>el.remove(),3800);}
function confirmModal(title,message,onConfirm,{danger=true,confirmText='Bekræft'}={}){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle" onclick="event.stopPropagation()"><header class="modal-header"><h2 id="modalTitle">${esc(title)}</h2><button class="icon-button" data-action="close-modal">${icon('x')}</button></header><div class="modal-body"><p>${nl2br(message)}</p></div><footer class="modal-actions"><button class="btn" data-action="close-modal">Annuller</button><button class="btn ${danger?'danger':'primary'}" id="modalConfirm">${esc(confirmText)}</button></footer></section></div>`;refreshIcons();$('#modalConfirm').onclick=()=>{root.innerHTML='';onConfirm();};}
function closeModal(){$('#modalRoot').innerHTML='';}
function errorView(err){console.error(err);app.innerHTML=`<section class="page error-panel"><h1>Appen snublede i teltpløkken</h1><p>Der kom en fejl, men du får ikke en tom hvid skærm. Det er da altid noget.</p><pre>${esc(err?.stack||err?.message||String(err))}</pre><div class="header-actions"><button class="btn primary" data-action="reload-app">Prøv igen</button><button class="btn" data-action="export-backup">Eksportér backup</button></div></section>`;refreshIcons();}

function renderCountdownMini(){
 const trip=data.settings.nextTrip||{};const target=new Date(`${trip.date||isoDate()}T09:00:00`);const diff=Math.max(0,target-Date.now());
 const days=Math.floor(diff/86400000),hours=Math.floor(diff/3600000)%24,minutes=Math.floor(diff/60000)%60,seconds=Math.floor(diff/1000)%60;
 return `<div class="countdown-mini"><h3>Næste campingtur</h3><div class="countdown-numbers"><div><strong>${String(days).padStart(2,'0')}</strong><span>Dage</span></div><div><strong>${String(hours).padStart(2,'0')}</strong><span>Timer</span></div><div><strong>${String(minutes).padStart(2,'0')}</strong><span>Min.</span></div><div><strong>${String(seconds).padStart(2,'0')}</strong><span>Sek.</span></div></div><div class="countdown-destination">til <strong>${esc(trip.title||'Næste eventyr')} 🏕️</strong>${trip.date?formatDate(trip.date):''}</div></div>`;
}

function pageHeader(title,subtitle,iconName='tent-tree',actions=''){return `<header class="page-header"><div class="page-title"><span class="page-title-icon">${icon(iconName)}</span><div><h1>${esc(title)}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div></div><div class="header-actions">${actions}</div></header>`;}
function statusChip(place){return `<span class="chip ${place.status==='wishlist'?'wish':''}">${place.status==='wishlist'?'♥ Vil besøge':'✓ Besøgt'}</span>`;}
function tagsHtml(tags=[]){return `<div class="tags">${tags.slice(0,6).map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</div>`;}
function placeCard(place){const date=place.status==='visited'?`Seneste besøg: ${formatDate(latestDate(place))}`:`Planlagt: ${formatDate(place.plannedDate)}`;return `<article class="place-card card" data-place-id="${esc(place.id)}"><div class="image-wrap"><img loading="lazy" src="${esc(firstImage(place))}" alt="${esc(place.name)}" onerror="this.src='assets/hero-camping.jpg'">${statusChip(place)}<button class="more-button" data-action="toggle-favorite" data-id="${esc(place.id)}" title="Favorit">${icon(place.favorite?'heart':'ellipsis-vertical')}</button></div><div class="place-card-body"><h2>${esc(place.name)}</h2><div class="place-meta">${esc([place.city,place.country].filter(Boolean).join(', '))}</div><div class="place-date">${esc(date)}</div>${place.status==='visited'?`<div class="place-rating">${stars(place.averageRating)} <span class="rating-number">${place.averageRating.toFixed(1).replace('.',',')}</span></div>`:''}${tagsHtml(place.tags)}<div class="place-actions"><a class="btn small" href="#/campingplads/${encodeURIComponent(place.id)}">${icon('circle-info')} Detaljer</a><a class="btn small" href="#/rediger/${encodeURIComponent(place.id)}">${icon('pencil')} Redigér</a></div></div></article>`;}

function renderOverview(){
 const s=data.settings;const visited=data.places.filter(p=>p.status==='visited');const wishes=data.places.filter(p=>p.status==='wishlist');
 const latest=[...visited].sort((a,b)=>latestDate(b).localeCompare(latestDate(a))).slice(0,3);
 const top=[...visited].sort((a,b)=>b.averageRating-a.averageRating).slice(0,3);
 const routes=allRoutes().slice(0,4);
 const sections={
  latest:`<section class="section-card card"><div class="section-title-row"><h2>Seneste campingbesøg</h2><a href="#/besoegte">Se alle</a></div><div class="mini-list">${latest.map(p=>`<a class="mini-item" href="#/campingplads/${encodeURIComponent(p.id)}"><img src="${esc(firstImage(p))}" alt=""><div><h3>${esc(p.name)}</h3><p>${esc([p.city,p.country].filter(Boolean).join(', '))}<br>${formatDate(latestDate(p))}</p></div><div>${stars(p.averageRating)}</div></a>`).join('')}</div></section>`,
  top:`<section class="section-card card"><div class="section-title-row"><h2>Bedst bedømte campingpladser</h2><a href="#/bedst">Se alle</a></div><div class="mini-list">${top.map((p,i)=>`<a class="mini-item" href="#/campingplads/${encodeURIComponent(p.id)}" style="grid-template-columns:38px 1fr auto"><span class="rank-badge rank-${i+1}">${i+1}</span><div><h3>${esc(p.name)}</h3><p>${esc([p.city,p.country].filter(Boolean).join(', '))}</p></div><div>${stars(p.averageRating)} <span class="rating-number">${p.averageRating.toFixed(1).replace('.',',')}</span></div></a>`).join('')}</div></section>`,
  wishlist:`<section class="section-card card"><div class="section-title-row"><h2>Udvalgte steder fra ønskelisten</h2><a href="#/oenskeliste">Se alle</a></div><div class="mini-list">${wishes.slice(0,3).map(p=>`<a class="mini-item" href="#/campingplads/${encodeURIComponent(p.id)}"><img src="${esc(firstImage(p))}" alt=""><div><h3>${esc(p.name)}</h3><p>${esc([p.city,p.country].filter(Boolean).join(', '))}<br>${formatDate(p.plannedDate)}</p></div><span class="heart-mark">♥</span></a>`).join('')}</div></section>`,
  routes:`<section class="section-card card span-2"><div class="section-title-row"><h2>Seneste eller udvalgte cykelruter</h2><a href="#/besoegte">Se alle</a></div>${routes.length?`<div class="route-mini-grid">${routes.map(r=>`<a class="route-mini" href="#/rute/${encodeURIComponent(r.placeId)}/${encodeURIComponent(r.id)}"><span class="route-icon">🚲</span><div><h3>${esc(r.name)}</h3><p>${esc(r.placeName)} · ${r.distance?formatKm(r.distance):'Afstand ikke beregnet'}</p></div>${icon('chevron-right')}</a>`).join('')}</div>`:`<div class="empty-state"><p>Der er ikke gemt cykelruter endnu.</p><a class="btn small primary" href="#/besoegte">Vælg campingplads</a></div>`}</section>`,
  sisi:`<section class="sisi-widget card"><img src="${esc(s.countdownImage||'assets/sisi-countdown.jpg')}" alt="Sisis nedtællingsur"><div class="sisi-overlay" id="sisiOverlay">${renderSisiOverlay()}</div></section>`
 };
 const visible=(s.sections||Object.keys(sections)).filter(id=>!s.hiddenSections?.includes(id)&&sections[id]);
 app.innerHTML=`<div class="page"><section class="dashboard-top"><div class="welcome"><h1>${greeting()} ${esc(s.names||'Sisi & Jan')}</h1><p>${esc(s.greetingText||'Her er jeres camping-overblik')}</p><div class="quick-actions"><button class="quick-action" data-action="open-search"><span class="qa-icon">${icon('search')}</span>Find campingplads</button><a class="quick-action" href="#/tilfoej?status=visited"><span class="qa-icon">${icon('plus-circle')}</span>Tilføj nyt besøg</a><a class="quick-action warm" href="#/tilfoej?status=wishlist"><span class="qa-icon">${icon('heart')}</span>Tilføj nyt ønske</a><a class="quick-action" href="#/kort"><span class="qa-icon">${icon('map')}</span>Åbn stort kort</a><a class="quick-action" href="#/indstillinger"><span class="qa-icon">${icon('settings')}</span>Indstillinger</a></div><div class="stat-grid"><article class="stat-card card"><strong>${visitCount()}</strong><span>Antal besøgte campingpladser</span><div class="stat-icon">✓</div></article><article class="stat-card card warm"><strong>${wishCount()}</strong><span>Antal ønskebesøg</span><div class="stat-icon">♥</div></article><article class="stat-card card"><strong>${countriesCount()}</strong><span>Antal besøgte lande</span><div class="stat-icon">🌍</div></article><article class="stat-card card"><strong>${routesCount()}</strong><span>Antal gemte cykelruter</span><div class="stat-icon">🚲</div></article></div></div><section class="map-card card"><div class="map-title">Oversigtskort</div><div id="overviewMap" class="map-container"></div><div class="map-legend"><span><i class="legend-dot visited"></i>Besøgt</span><span><i class="legend-dot wish"></i>Vil besøge</span></div></section></section><section class="dashboard-grid">${visible.map(id=>sections[id]).join('')}</section></div>`;
 refreshIcons();setTimeout(()=>CampingMaps.createMap('overviewMap',{places:data.places,style:s.mapStyle,provider:s.mapProvider,googleKey:s.googleMapsKey,fullscreen:false,padding:45,maxZoom:6}),20);startCountdown();
}

function renderSisiOverlay(){const target=new Date(`${data.settings.nextTrip?.date||isoDate()}T09:00:00`);const diff=Math.max(0,target-Date.now());const d=Math.floor(diff/86400000),h=Math.floor(diff/3600000)%24,m=Math.floor(diff/60000)%60,sec=Math.floor(diff/1000)%60;return `<small>SISIS NEDTÆLLINGSUR</small><strong>${String(d).padStart(2,'0')}:${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}</strong><small>DAGE · TIMER · MINUTTER · SEKUNDER</small>`;}
function startCountdown(){clearInterval(countdownTimer);countdownTimer=setInterval(()=>{const side=$('#sidebarCountdown');if(side)side.innerHTML=renderCountdownMini();const overlay=$('#sisiOverlay');if(overlay)overlay.innerHTML=renderSisiOverlay();},1000);}

function filteredVisited(){let list=data.places.filter(p=>p.status==='visited');const q=ui.visitedSearch.trim().toLowerCase();if(q)list=list.filter(p=>[p.name,p.city,p.region,p.country,...p.tags].join(' ').toLowerCase().includes(q));if(ui.visitedSort==='rating')list.sort((a,b)=>b.averageRating-a.averageRating);else if(ui.visitedSort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'da'));else list.sort((a,b)=>latestDate(b).localeCompare(latestDate(a)));return list;}
function renderVisited(){const list=filteredVisited();app.innerHTML=`<div class="page">${pageHeader('Besøgte campingpladser','Alle jeres minder samlet ét sted','map-pin-check',`<a class="btn primary" href="#/tilfoej?status=visited">${icon('plus')} <span class="hide-mobile">Tilføj besøg</span></a>`)}<div class="toolbar"><label class="search-box">${icon('search')}<input id="visitedSearch" value="${esc(ui.visitedSearch)}" placeholder="Søg efter navn, by, land eller tags..."></label><span class="small-muted">Sortér efter</span><div class="segmented"><button data-action="visited-sort" data-sort="latest" class="${ui.visitedSort==='latest'?'active':''}">Seneste besøg</button><button data-action="visited-sort" data-sort="rating" class="${ui.visitedSort==='rating'?'active':''}">Bedste vurdering</button><button data-action="visited-sort" data-sort="name" class="${ui.visitedSort==='name'?'active':''}">Navn</button></div></div>${list.length?`<section class="place-grid">${list.map(placeCard).join('')}</section>`:`<section class="empty-state card"><div class="empty-icon">${icon('tent-tree')}</div><h2>Ingen campingpladser fundet</h2><p>Prøv et andet søgeord eller tilføj jeres første besøg.</p><a class="btn primary" href="#/tilfoej?status=visited">Tilføj campingplads</a></section>`}<p class="small-muted text-right mt-1">Viser ${list.length} af ${visitCount()} campingpladser</p></div>`;refreshIcons();setTimeout(()=>$('#visitedSearch')?.focus({preventScroll:true}),0);}

function filteredWishes(){let list=data.places.filter(p=>p.status==='wishlist');const q=ui.wishSearch.trim().toLowerCase();if(q)list=list.filter(p=>[p.name,p.city,p.region,p.country,p.description,...p.tags].join(' ').toLowerCase().includes(q));if(ui.wishSort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'da'));else if(ui.wishSort==='updated')list.sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));else list.sort((a,b)=>(a.plannedDate||'9999').localeCompare(b.plannedDate||'9999'));return list;}
function renderWishlist(){const list=filteredWishes();app.innerHTML=`<div class="page">${pageHeader('Campingpladser vi vil besøge','Fremtidige eventyr venter','heart',`<a class="btn" href="#/kort">${icon('map')} <span class="hide-mobile">Vis på kort</span></a><a class="btn primary" href="#/tilfoej?status=wishlist">${icon('plus')} <span class="hide-mobile">Tilføj ønskebesøg</span></a>`)}<div class="toolbar"><label class="search-box">${icon('search')}<input id="wishSearch" value="${esc(ui.wishSearch)}" placeholder="Søg i ønskelisten..."></label><select id="wishSort" class="form-control" style="width:auto"><option value="planned" ${ui.wishSort==='planned'?'selected':''}>Planlagt dato</option><option value="updated" ${ui.wishSort==='updated'?'selected':''}>Senest opdateret</option><option value="name" ${ui.wishSort==='name'?'selected':''}>Navn</option></select></div><div class="segmented mb-0"><button class="active">Alle ønskebesøg · ${wishCount()}</button><button>Planlagt i år · ${list.filter(p=>p.plannedDate?.startsWith(String(new Date().getFullYear()))).length}</button><button>Sommer · ${list.filter(p=>['06','07','08'].includes(p.plannedDate?.slice(5,7))).length}</button></div><section class="wishlist-list mt-2">${list.map(p=>`<article class="wishlist-row card"><img src="${esc(firstImage(p))}" alt="${esc(p.name)}"><div><h2>${esc(p.name)}</h2><div class="place-meta">${esc([p.city,p.country].filter(Boolean).join(', '))} · 📅 Planlagt: ${formatDate(p.plannedDate)}</div><p class="description">${esc(p.description)}</p>${tagsHtml(p.tags)}</div><div class="wishlist-row-actions"><span class="heart-mark">♥</span><a class="btn small" href="#/campingplads/${encodeURIComponent(p.id)}">${icon('circle-info')} Detaljer</a><a class="btn small" href="#/rediger/${encodeURIComponent(p.id)}">${icon('pencil')} Redigér</a><button class="btn small primary" data-action="mark-visited" data-id="${esc(p.id)}">${icon('check')} Besøgt</button></div></article>`).join('')}</section>${!list.length?`<section class="empty-state card"><div class="empty-icon">${icon('heart')}</div><h2>Ønskelisten er tom</h2><p>Det er enten imponerende selvkontrol eller alt for få ferieplaner.</p><a class="btn primary" href="#/tilfoej?status=wishlist">Tilføj et ønske</a></section>`:''}</div>`;refreshIcons();}

function renderBest(){const visited=data.places.filter(p=>p.status==='visited').sort((a,b)=>b.averageRating-a.averageRating);const top=visited.slice(0,3);const avg=visited.length?visited.reduce((s,p)=>s+p.averageRating,0)/visited.length:0;const winners=data.ratingCategories.map(cat=>({cat,place:[...visited].sort((a,b)=>num(b.ratings?.[cat.id])-num(a.ratings?.[cat.id]))[0]})).filter(x=>x.place&&num(x.place.ratings?.[x.cat.id])>0).slice(0,4);app.innerHTML=`<div class="page">${pageHeader('Bedst bedømte campingpladser','Jeres personlige rangliste baseret på egne vurderinger','trophy')}<div class="podium-layout"><section class="podium">${top.length?top.map((p,i)=>{const order=[1,0,2][i]??i;return ''}).join(''):''}${top[1]?podiumCard(top[1],2):''}${top[0]?podiumCard(top[0],1,true):''}${top[2]?podiumCard(top[2],3):''}</section><aside class="podium-sidebar"><div><section class="average-card card"><strong>${avg.toFixed(1).replace('.',',')} ${stars(avg)}</strong><span>Gennemsnitlig vurdering</span><p class="small-muted">Baseret på ${visited.length} campingpladser</p></section><section class="top-list card"><h3>Top 5 samlet vurdering</h3>${visited.slice(0,5).map((p,i)=>`<a class="top-list-row" href="#/campingplads/${encodeURIComponent(p.id)}"><span class="n">${i+1}</span><span>${esc(p.name)}<br>${stars(p.averageRating)}</span><strong>${p.averageRating.toFixed(1).replace('.',',')}</strong></a>`).join('')}</section></div><section class="card card-pad"><h3 class="mt-0">Sådan vurderes pladserne</h3><p class="small-muted">Ranglisten bruger kun jeres egne stjerner. Ingen mystisk algoritme med slips og regneark.</p><ul class="small-muted"><li>Samlet gennemsnit</li><li>Kategorivindere</li><li>Opdateres straks efter redigering</li></ul><a class="btn primary" href="#/vurderingskategorier">Redigér kategorier</a></section></aside></div><section class="category-winners"><div class="section-title-row"><div><h2>Kategorivindere</h2><p class="small-muted">De bedste campingpladser i hver kategori</p></div></div><div class="winner-grid">${winners.map(({cat,place})=>`<article class="winner-card card"><img src="${esc(firstImage(place))}" alt="${esc(place.name)}"><div class="winner-card-body"><h3>${icon(cat.icon||'star')} Bedste ${esc(cat.name.toLowerCase())}</h3><h4>${esc(place.name)}</h4>${stars(place.ratings[cat.id])} <strong>${num(place.ratings[cat.id]).toFixed(1).replace('.',',')}</strong><div class="mt-1"><a class="btn small" href="#/campingplads/${encodeURIComponent(place.id)}">Se campingplads</a></div></div></article>`).join('')}</div></section></div>`;refreshIcons();}
function podiumCard(p,rank,first=false){return `<article class="podium-card card ${first?'first':''}"><span class="podium-medal rank-${rank}">${rank}</span><img src="${esc(firstImage(p))}" alt="${esc(p.name)}"><div class="podium-body"><h2>${esc(p.name)}</h2><p class="place-meta">${esc([p.city,p.country].filter(Boolean).join(', '))}</p><div>${stars(p.averageRating)} <span class="rating-number">${p.averageRating.toFixed(1).replace('.',',')}</span></div><div class="mt-1"><a class="btn ${first?'warm':''}" href="#/campingplads/${encodeURIComponent(p.id)}">Se campingplads ${icon('arrow-right')}</a></div></div></article>`;}

function renderMap(){let places=data.places.filter(p=>ui.mapFilter==='all'||(ui.mapFilter==='visited'?p.status==='visited':p.status==='wishlist'));const storedQ=ui.mapStoredSearch.trim().toLowerCase();if(storedQ)places=places.filter(p=>[p.name,p.city,p.region,p.country,...(p.tags||[])].join(' ').toLowerCase().includes(storedQ));app.innerHTML=`<div class="page"><section class="full-map-page"><div id="mainMap" class="map-container"></div><div class="map-topbar"><div class="segmented"><button data-action="map-filter" data-filter="all" class="${ui.mapFilter==='all'?'active':''}">Alle</button><button data-action="map-filter" data-filter="visited" class="${ui.mapFilter==='visited'?'active':''}">Besøgte</button><button data-action="map-filter" data-filter="wishlist" class="${ui.mapFilter==='wishlist'?'active':''}">Vil besøge</button></div><button class="btn" data-action="find-missing-coords">${icon('locate-fixed')} <span>Find manglende koordinater</span></button><button class="btn icon-only" data-action="show-location" title="Vis min placering">${icon('navigation')}</button></div><form id="mapSearchForm" class="map-search-panel"><label>Søg blandt gemte campingpladser<input id="mapStoredSearch" value="${esc(ui.mapStoredSearch)}" placeholder="Søg i gemte campingpladser..."></label><label>Søg efter nye campingpladser online<input id="mapOnlineSearch" placeholder="Navn, by eller område..."></label><button class="btn primary" type="submit">${icon('search')} Søg</button></form>${ui.mapResults.length?`<div class="search-results-pop">${ui.mapResults.map((r,i)=>`<div class="search-result"><div><h4>${esc(r.name)}</h4><p>${esc(r.label||[r.city,r.country].filter(Boolean).join(', '))}</p></div><div><button class="btn small" data-action="add-search-result" data-index="${i}" data-status="visited">Besøgt</button> <button class="btn small warm" data-action="add-search-result" data-index="${i}" data-status="wishlist">Vil besøge</button></div></div>`).join('')}</div>`:''}</section></div>`;refreshIcons();setTimeout(()=>CampingMaps.createMap('mainMap',{places,style:data.settings.mapStyle,provider:data.settings.mapProvider,googleKey:data.settings.googleMapsKey,geolocate:true,userLocation:ui.userLocation,padding:70,maxZoom:8}),20);}

function renderSettings(){const s=data.settings;const sectionNames={latest:'Seneste besøg',top:'Top 3 samlet vurdering',wishlist:'Favoritter fra ønskelisten',routes:'Seneste cykelruter',sisi:'Sisis nedtællingsur'};app.innerHTML=`<div class="page"><section class="settings-hero"><img src="${esc(s.coverImage||'assets/cover.jpg')}" alt="Campinglandskab"><div class="settings-hero-text"><h1>${icon('settings')} Indstillinger</h1><p>Tilpas appen, så den passer til jeres campingoplevelser</p></div></section><form id="settingsForm"><section class="settings-grid">
 <article class="settings-card card"><h2>${icon('square-pen')} Appnavn og forsidetekster</h2><p>Tilpas navn og de tekster, der vises.</p><div class="form-row"><label>Appnavn</label><input class="form-control" name="appName" value="${esc(s.appName)}"></div><div class="form-row"><label>Undertitel</label><input class="form-control" name="subtitle" value="${esc(s.subtitle)}"></div><div class="form-row"><label>Navne</label><input class="form-control" name="names" value="${esc(s.names)}"></div><div class="form-row"><label>Forsidetekst</label><input class="form-control" name="greetingText" value="${esc(s.greetingText)}"></div></article>
 <article class="settings-card card"><h2>${icon('calendar-days')} Næste campingtur og nedtælling</h2><p>Vælg næste tur og vis Sisis ur.</p><div class="form-row"><label>Næste tur</label><input class="form-control" name="tripTitle" value="${esc(s.nextTrip?.title||'')}"></div><div class="form-row"><label>Måldato</label><input class="form-control" type="date" name="tripDate" value="${esc(s.nextTrip?.date||'')}"></div><label class="form-check"><span class="switch"><input type="checkbox" name="showCountdown" ${s.showCountdown?'checked':''}><span></span></span>Vis nedtælling</label><div class="mt-1"><img src="${esc(s.countdownImage||'assets/sisi-countdown.jpg')}" alt="Sisis ur" style="height:125px;width:100%;object-fit:cover;border-radius:12px"></div></article>
 <article class="settings-card card"><h2>${icon('image')} Valg af coverbillede</h2><p>Vælg det billede, der vises i indstillinger og på forsiden.</p><img src="${esc(s.coverImage||'assets/cover.jpg')}" alt="Valgt cover" style="height:130px;width:100%;object-fit:cover;border-radius:12px"><div class="mt-1"><label class="btn small">${icon('image-plus')} Skift billede<input id="coverUpload" type="file" accept="image/*" hidden></label></div></article>
 <article class="settings-card card"><h2>${icon('scaling')} Størrelsesskalering af layout</h2><p>Juster tekst, elementer, kort og knapper.</p><div class="range-wrap"><span>A</span><input id="scaleInput" type="range" name="scale" min="0.8" max="1.25" step="0.05" value="${num(s.scale,1)}"><span style="font-size:1.35rem">A</span></div><p id="scaleValue" class="small-muted text-right">${Math.round(num(s.scale,1)*100)} %</p></article>
 <article class="settings-card card"><h2>${icon('sun')} Tema og farver</h2><p>Vælg lyst eller mørkt tema og hovedfarve.</p><div class="segmented"><button type="button" data-action="theme-choice" data-theme="light" class="${s.theme!=='dark'?'active':''}">${icon('sun')} Lyst</button><button type="button" data-action="theme-choice" data-theme="dark" class="${s.theme==='dark'?'active':''}">${icon('moon')} Mørkt</button></div><input type="hidden" name="theme" value="${esc(s.theme)}"><div class="color-palette mt-1">${['#1f3d2e','#4e6b3a','#b87d24','#a65a2a','#a4422f'].map(c=>`<button type="button" class="color-swatch ${s.accent===c?'active':''}" style="background:${c}" data-action="accent-choice" data-color="${c}" aria-label="Vælg farve ${c}"></button>`).join('')}</div><input type="hidden" name="accent" value="${esc(s.accent)}"></article>
 <article class="settings-card card"><h2>${icon('layout-grid')} Kompakt eller luftig forside</h2><p>Vælg hvor meget luft der bruges.</p><div class="segmented"><button type="button" data-action="density-choice" data-density="compact" class="${s.density!=='airy'?'active':''}">Kompakt</button><button type="button" data-action="density-choice" data-density="airy" class="${s.density==='airy'?'active':''}">Luftig</button></div><input type="hidden" name="density" value="${esc(s.density)}"></article>
 <article class="settings-card card span-2"><h2>${icon('list-restart')} Vis, skjul og rækkefølge af forsidesektioner</h2><p>Vælg hvilke sektioner der vises, og flyt dem op eller ned.</p><div class="order-list">${(s.sections||[]).map((id,i)=>`<div class="order-item" data-section-id="${id}"><span class="drag">${icon('grip-vertical')}</span><label class="switch"><input type="checkbox" data-action="section-toggle" data-section="${id}" ${!s.hiddenSections?.includes(id)?'checked':''}><span></span></label><span>${esc(sectionNames[id]||id)}</span><button type="button" class="icon-button" data-action="section-move" data-direction="up" data-section="${id}" ${i===0?'disabled':''}>${icon('arrow-up')}</button><button type="button" class="icon-button" data-action="section-move" data-direction="down" data-section="${id}" ${i===(s.sections||[]).length-1?'disabled':''}>${icon('arrow-down')}</button></div>`).join('')}</div></article>
 <article class="settings-card card"><h2>${icon('star')} Vurderingskategorier</h2><p>Omdøb, tilføj eller fjern jeres egne kategorier.</p><p><strong>${data.ratingCategories.length}</strong> aktive kategorier</p><a class="btn" href="#/vurderingskategorier">${icon('pencil')} Redigér kategorier</a></article>
 <article class="settings-card card"><h2>${icon('map')} Kort og API-nøgler</h2><p>OpenFreeMap virker uden nøgle. ORS bruges til søgning og cykelruter.</p><div class="form-row"><label>Kortmotor</label><select class="form-control" name="mapProvider"><option value="maplibre" ${s.mapProvider!=='google'?'selected':''}>OpenFreeMap / MapLibre</option><option value="google" ${s.mapProvider==='google'?'selected':''}>Google Maps (reserve)</option></select></div><div class="form-row"><label>Kortstil</label><select class="form-control" name="mapStyle">${['liberty','positron','bright','fiord','dark'].map(v=>`<option value="${v}" ${s.mapStyle===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></div><div class="field"><label>Openrouteservice API-nøgle</label><input class="form-control" name="orsKey" type="password" value="${esc(s.orsKey||'')}" autocomplete="off"></div><div class="field mt-1"><label>Google Maps API-nøgle (valgfri)</label><input class="form-control" name="googleMapsKey" type="password" value="${esc(s.googleMapsKey||'')}" autocomplete="off"></div><div class="api-status">${icon('circle-check')} OpenFreeMap kræver ingen API-nøgle</div><button type="button" class="btn small mt-1" data-action="test-api">${icon('plug-zap')} Test forbindelse</button></article>
 <article class="settings-card card"><h2>${icon('database-backup')} Sikkerhedskopi</h2><p>Flyt data mellem computer, tablet og mobil.</p><div class="header-actions" style="justify-content:flex-start"><button type="button" class="btn" data-action="export-backup">${icon('download')} Eksportér</button><button type="button" class="btn" data-action="import-backup">${icon('upload')} Importér</button></div><p class="small-muted">API-nøgler udelades automatisk fra backupfilen.</p></article>
 <article class="settings-card card danger-zone"><h2>${icon('trash-2')} Nulstilling / rydning af campingdata</h2><p>Dette kan ikke fortrydes. Tag gerne en backup først.</p><button type="button" class="btn danger" data-action="reset-data">${icon('trash-2')} Nulstil data</button></article>
 </section><div class="sticky-actions mt-2"><button class="btn primary" type="submit">${icon('save')} Gem indstillinger</button></div></form></div>`;refreshIcons();}

function blankPlace(status='visited'){return {id:uid('camp'),status,name:'',address:'',postalCode:'',city:'',region:'',country:'',website:'',phone:'',coords:{lat:'',lng:''},visitDates:status==='visited'?[isoDate()]:[],plannedDate:status==='wishlist'?isoDate(new Date(Date.now()+30*86400000)):'',description:'',notes:'',tags:[],ratings:{},images:[],sights:[],routes:[],favorite:false,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};}

function renderPlaceEditor(place,isNew=false){
 ui.editingImages=[...(place.images||[])];
 const title=isNew?'Tilføj campingplads':`Redigér ${place.name}`;
 const dateRows=(place.visitDates?.length?place.visitDates:['']).map((d,i)=>`<div class="array-row visit-date-row"><input class="form-control" type="date" value="${esc(d)}"><span></span>${i?`<button type="button" class="btn small danger" data-action="remove-array-row">${icon('trash-2')}</button>`:''}</div>`).join('');
 const sightRows=(place.sights?.length?place.sights:[{name:'',description:'',link:''}]).map((s,i)=>`<div class="array-row sight-editor-row"><input class="form-control" data-field="name" value="${esc(s.name||'')}" placeholder="Navn"><input class="form-control" data-field="description" value="${esc(s.description||'')}" placeholder="Beskrivelse"><button type="button" class="btn small danger" data-action="remove-array-row">${icon('trash-2')}</button><input class="form-control" data-field="link" value="${esc(s.link||'')}" placeholder="Link til placering (valgfrit)" style="grid-column:1/-1"></div>`).join('');
 app.innerHTML=`<div class="page form-page">${pageHeader(title,isNew?'Søg og udfyld automatisk – eller skriv oplysningerne manuelt.':'Alle oplysninger kan ændres.','square-pen',`<a class="btn" href="${isNew?'#/besoegte':`#/campingplads/${encodeURIComponent(place.id)}`}">${icon('x')} Annuller</a>`)}<form id="placeForm" data-id="${esc(place.id)}" data-new="${isNew?'true':'false'}">
 <section class="form-section card"><h2>1. Status og søgning</h2><div class="status-choice"><label><input type="radio" name="status" value="visited" ${place.status==='visited'?'checked':''}><span>✓ <strong>Besøgt campingplads</strong><br><small>Et sted I allerede har besøgt</small></span></label><label><input type="radio" name="status" value="wishlist" ${place.status==='wishlist'?'checked':''}><span>♥ <strong>Campingplads vi vil besøge</strong><br><small>Et fremtidigt eventyr</small></span></label></div><div class="toolbar mt-2"><label class="search-box">${icon('search')}<input id="formPlaceSearch" value="${esc(place.name)}" placeholder="Søg efter campingpladsens navn eller område..."></label><button type="button" class="btn primary" data-action="search-place-form">Søg online</button></div></section>
 <section class="form-section card"><h2>2. Grundoplysninger</h2><div class="form-grid"><div class="field full"><label>Navn *</label><input class="form-control" name="name" required value="${esc(place.name)}"></div><div class="field full"><label>Adresse</label><input class="form-control" name="address" value="${esc(place.address)}"></div><div class="field"><label>Postnummer</label><input class="form-control" name="postalCode" value="${esc(place.postalCode)}"></div><div class="field"><label>By</label><input class="form-control" name="city" value="${esc(place.city)}"></div><div class="field"><label>Område / region</label><input class="form-control" name="region" value="${esc(place.region)}"></div><div class="field"><label>Land</label><input class="form-control" name="country" value="${esc(place.country)}"></div><div class="field"><label>Hjemmeside</label><input class="form-control" name="website" type="url" value="${esc(place.website)}" placeholder="https://..."></div><div class="field"><label>Telefonnummer</label><input class="form-control" name="phone" value="${esc(place.phone)}"></div></div></section>
 <section class="form-section card"><h2>3. Datoer og kortplacering</h2><div class="form-grid"><div class="field"><label>Planlagt besøgsdato</label><input class="form-control" type="date" name="plannedDate" value="${esc(place.plannedDate)}"></div><div class="field"><label>Besøgsdatoer</label><div id="visitDatesList" class="array-list">${dateRows}</div><button type="button" class="btn small mt-1" data-action="add-visit-date">${icon('plus')} Tilføj besøgsdato</button></div><div class="field"><label>Breddegrad</label><input class="form-control" name="lat" value="${Number.isFinite(num(place.coords?.lat,NaN))?String(place.coords.lat):''}" placeholder="56,1234"></div><div class="field"><label>Længdegrad</label><input class="form-control" name="lng" value="${Number.isFinite(num(place.coords?.lng,NaN))?String(place.coords.lng):''}" placeholder="8,1234"></div><div class="full header-actions" style="justify-content:flex-start"><button type="button" class="btn" data-action="use-current-location">${icon('locate-fixed')} Brug aktuel placering</button><button type="button" class="btn" data-action="preview-form-map">${icon('map-pin')} Vis placering</button></div><div id="formMapPreview" class="detail-map full" hidden></div></div></section>
 <section class="form-section card"><h2>4. Beskrivelse, noter og tags</h2><div class="form-grid"><div class="field full"><label>Beskrivelse</label><textarea class="form-control" name="description">${esc(place.description)}</textarea></div><div class="field full"><label>Private noter</label><textarea class="form-control" name="notes">${esc(place.notes)}</textarea></div><div class="field full"><label>Tags</label><input class="form-control" name="tags" value="${esc((place.tags||[]).join(', '))}" placeholder="Natur, Ved vandet, Hundevenlig, Cykelruter"><small>Adskil tags med komma.</small></div></div></section>
 <section class="form-section card"><h2>5. Vurderinger</h2><div class="rating-editor">${data.ratingCategories.map(cat=>{const rating=num(place.ratings?.[cat.id]);return `<div class="rating-row"><span>${icon(cat.icon||'star')} ${esc(cat.name)}</span><div class="star-input" data-category="${esc(cat.id)}"><input type="hidden" name="rating_${esc(cat.id)}" value="${rating}">${[1,2,3,4,5].map(n=>`<button type="button" class="${n<=rating?'on':''}" data-action="set-rating" data-value="${n}" aria-label="${n} stjerner">★</button>`).join('')}</div></div>`;}).join('')}</div></section>
 <section class="form-section card"><h2>6. Billeder</h2><label class="btn">${icon('image-plus')} Tilføj billeder<input id="placeImages" type="file" accept="image/*" multiple hidden></label><span class="small-muted"> Billeder komprimeres automatisk.</span><div id="imagePreviewGrid" class="image-preview-grid">${renderImagePreviews()}</div></section>
 <section class="form-section card"><h2>7. Seværdigheder</h2><div id="sightsEditor" class="array-list">${sightRows}</div><button type="button" class="btn small mt-1" data-action="add-sight">${icon('plus')} Tilføj seværdighed</button></section>
 ${!isNew?`<section class="form-section card"><h2>8. Cykelruter</h2><div class="routes-list">${(place.routes||[]).map(r=>`<div class="route-row"><h3>${esc(r.name)}</h3><p>${r.distance?formatKm(r.distance):'Ikke beregnet'} · ${esc(r.difficulty||'')}</p><div class="mt-1"><a class="btn small" href="#/rute-editor/${encodeURIComponent(place.id)}/${encodeURIComponent(r.id)}">Redigér</a> <button type="button" class="btn small danger" data-action="delete-route" data-place="${esc(place.id)}" data-route="${esc(r.id)}">Slet</button></div></div>`).join('')||'<p class="small-muted">Ingen cykelruter endnu.</p>'}</div><a class="btn primary mt-1" href="#/rute-editor/${encodeURIComponent(place.id)}/ny">${icon('bike')} Opret cykelrute</a></section>`:''}
 <div class="sticky-actions"><button type="button" class="btn" data-action="save-and-view">${icon('eye')} Gem og vis</button><button class="btn primary" type="submit">${icon('save')} Gem campingplads</button>${!isNew?`<button type="button" class="btn danger" data-action="delete-place" data-id="${esc(place.id)}">${icon('trash-2')} Slet</button>`:''}</div></form></div>`;refreshIcons();}

function renderImagePreviews(){return ui.editingImages.map((src,i)=>`<div class="image-preview"><img src="${esc(src)}" alt="Billede ${i+1}"><button type="button" data-action="remove-image" data-index="${i}" aria-label="Fjern billede">×</button></div>`).join('');}

function renderPlaceDetail(place){
 const routeRows=(place.routes||[]).map(r=>`<a class="route-row" href="#/rute/${encodeURIComponent(place.id)}/${encodeURIComponent(r.id)}"><h3>🚲 ${esc(r.name)}</h3><p>${r.distance?formatKm(r.distance):'Afstand ikke beregnet'} · ${r.duration?formatDuration(r.duration):''} · ${esc(r.difficulty||'')}</p></a>`).join('');
 app.innerHTML=`<div class="page"><section class="detail-hero"><img src="${esc(firstImage(place))}" alt="${esc(place.name)}"><div class="detail-hero-content"><div>${statusChip(place)}<h1>${esc(place.name)}</h1><p>${esc([place.city,place.region,place.country].filter(Boolean).join(', '))}</p></div>${place.status==='visited'?`<div class="detail-rating">${stars(place.averageRating)} <strong>${place.averageRating.toFixed(1).replace('.',',')}</strong></div>`:''}</div></section><div class="page-header"><div><p class="small-muted">${place.status==='visited'?`Seneste besøg: ${formatDate(latestDate(place))}`:`Planlagt dato: ${formatDate(place.plannedDate)}`}</p></div><div class="header-actions"><a class="btn primary" href="#/rediger/${encodeURIComponent(place.id)}">${icon('pencil')} Redigér</a>${CampingMaps.validCoords(place)?`<a class="btn" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${place.coords.lat},${place.coords.lng}`)}">${icon('map-pin')} Google Maps</a>`:''}</div></div><section class="detail-grid"><div class="detail-stack"><article class="section-card card"><h2 class="mt-0">Om campingpladsen</h2><p>${nl2br(place.description||'Ingen beskrivelse endnu.')}</p>${tagsHtml(place.tags)}${place.notes?`<div class="divider"></div><h3>Private noter</h3><p>${nl2br(place.notes)}</p>`:''}</article>${place.status==='visited'?`<article class="section-card card"><div class="section-title-row"><h2>Vurderinger</h2><strong>${place.averageRating.toFixed(1).replace('.',',')} / 5</strong></div><div class="rating-breakdown">${data.ratingCategories.map(cat=>{const r=num(place.ratings?.[cat.id]);return `<div class="rating-breakdown-row"><span>${icon(cat.icon||'star')} ${esc(cat.name)}</span><div class="bar"><span style="width:${r/5*100}%"></span></div><strong>${r?r.toFixed(1).replace('.',','):'–'}</strong></div>`;}).join('')}</div></article>`:''}<article class="section-card card"><div class="section-title-row"><h2>Billedgalleri</h2><a href="#/rediger/${encodeURIComponent(place.id)}">Tilføj/fjern</a></div>${place.images?.length?`<div class="gallery">${place.images.map((src,i)=>`<img src="${esc(src)}" alt="${esc(place.name)} billede ${i+1}" data-action="open-image" data-place="${esc(place.id)}" data-index="${i}">`).join('')}</div>`:'<p class="small-muted">Ingen billeder er tilføjet.</p>'}</article><article class="section-card card"><div class="section-title-row"><h2>Seværdigheder i området</h2><a href="#/rediger/${encodeURIComponent(place.id)}">Redigér</a></div><div class="sights-list">${(place.sights||[]).map(s=>`<div class="sight-row"><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p>${s.link?`<a class="text-link" target="_blank" rel="noopener" href="${esc(s.link)}">Åbn placering</a>`:''}</div>`).join('')||'<p class="small-muted">Ingen seværdigheder er tilføjet.</p>'}</div></article><article class="section-card card"><div class="section-title-row"><h2>Gemte cykelruter</h2><a href="#/rute-editor/${encodeURIComponent(place.id)}/ny">Opret rute</a></div><div class="routes-list">${routeRows||'<p class="small-muted">Ingen cykelruter er gemt.</p>'}</div></article></div><aside class="detail-stack"><article class="section-card card"><h2 class="mt-0">Placering</h2><div id="detailMap" class="detail-map"></div></article><article class="section-card card"><h2 class="mt-0">Kontakt og oplysninger</h2><div class="contact-list"><div>${icon('map-pin')} ${esc([place.address,place.postalCode,place.city,place.region,place.country].filter(Boolean).join(', ')||'Adresse ikke angivet')}</div>${place.website?`<a target="_blank" rel="noopener" href="${esc(place.website)}">${icon('globe')} ${esc(place.website)}</a>`:''}${place.phone?`<a href="tel:${esc(place.phone)}">${icon('phone')} ${esc(place.phone)}</a>`:''}<div>${icon('calendar')} ${place.visitDates?.length?place.visitDates.map(d=>formatDate(d)).join(', '):'Ingen besøgsdatoer'}</div></div></article><article class="section-card card"><h2 class="mt-0">Hurtige handlinger</h2><div class="header-actions" style="justify-content:flex-start"><button class="btn" data-action="toggle-favorite" data-id="${esc(place.id)}">${icon('heart')} ${place.favorite?'Fjern favorit':'Tilføj favorit'}</button>${place.status==='wishlist'?`<button class="btn primary" data-action="mark-visited" data-id="${esc(place.id)}">${icon('check')} Markér som besøgt</button>`:''}<button class="btn" data-action="share-place" data-id="${esc(place.id)}">${icon('share-2')} Del</button></div></article></aside></section></div>`;refreshIcons();setTimeout(()=>CampingMaps.createMap('detailMap',{places:[place],style:data.settings.mapStyle,provider:data.settings.mapProvider,googleKey:data.settings.googleMapsKey,fullscreen:false,padding:70,maxZoom:14}),20);}

function parseCoordPair(value){const parts=String(value||'').trim().split(/[;,\s]+/).filter(Boolean).map(v=>num(v,NaN));if(parts.length<2||!parts.every(Number.isFinite))return null;return {lat:parts[0],lng:parts[1]};}
function renderRouteEditor(place,routeId){const existing=routeId&&routeId!=='ny'?(place.routes||[]).find(r=>r.id===routeId):null;const route=existing||{id:uid('route'),name:'',start:place.name,end:'',waypoints:[],difficulty:'Let',description:'',distance:0,duration:0,coordinates:[],googleMapsLink:''};ui.routeDraft=structuredClone(route);const start=route.coordinates?.[0]?[route.coordinates[0][1],route.coordinates[0][0]].join(', '):CampingMaps.validCoords(place)?`${place.coords.lat}, ${place.coords.lng}`:'';const end=route.coordinates?.at(-1)?[route.coordinates.at(-1)[1],route.coordinates.at(-1)[0]].join(', '):'';const waypoints=(route.coordinates||[]).slice(1,-1).map(c=>`${c[1]}, ${c[0]}`).join('\n');app.innerHTML=`<div class="page form-page">${pageHeader(existing?'Redigér cykelrute':'Opret cykelrute',`Omkring ${place.name}`,'bike',`<a class="btn" href="#/campingplads/${encodeURIComponent(place.id)}">${icon('x')} Annuller</a>`)}<form id="routeForm" data-place="${esc(place.id)}" data-route="${esc(route.id)}"><section class="form-section card"><h2>Ruteoplysninger</h2><div class="form-grid"><div class="field full"><label>Rutenavn *</label><input class="form-control" name="name" required value="${esc(route.name)}" placeholder="F.eks. Kystvejen rundt"></div><div class="field"><label>Startsted</label><input class="form-control" name="start" value="${esc(route.start||place.name)}"></div><div class="field"><label>Slutsted</label><input class="form-control" name="end" value="${esc(route.end)}"></div><div class="field"><label>Startkoordinat (lat, lng) *</label><input class="form-control" name="startCoords" value="${esc(start)}" placeholder="56.123, 8.123"></div><div class="field"><label>Slutkoordinat (lat, lng) *</label><input class="form-control" name="endCoords" value="${esc(end)}" placeholder="56.234, 8.234"></div><div class="field full"><label>Mellempunkter – ét koordinatsæt pr. linje</label><textarea class="form-control" name="waypointCoords" placeholder="56.150, 8.150\n56.180, 8.190">${esc(waypoints)}</textarea></div><div class="field"><label>Sværhedsgrad</label><select class="form-control" name="difficulty">${['Let','Mellem','Udfordrende'].map(v=>`<option ${route.difficulty===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Google Maps-link</label><input class="form-control" name="googleMapsLink" type="url" value="${esc(route.googleMapsLink||'')}" placeholder="Indsæt delt link"></div><div class="field full"><label>Rutebeskrivelse</label><textarea class="form-control" name="description">${esc(route.description)}</textarea></div></div><div class="header-actions mt-2" style="justify-content:flex-start"><button type="button" class="btn primary" data-action="calculate-route">${icon('route')} Beregn med Openrouteservice</button><button type="button" class="btn" data-action="route-use-place">${icon('map-pin')} Brug campingplads som start</button></div></section><section class="form-section card"><div class="section-title-row"><h2>Rutekort</h2><div id="routeSummary">${route.distance?`${formatKm(route.distance)} · ${formatDuration(route.duration)}`:'Ruten er ikke beregnet endnu.'}</div></div><div id="routeEditorMap" class="route-detail-map"></div></section><div class="sticky-actions"><button class="btn primary" type="submit">${icon('save')} Gem cykelrute</button>${existing?`<button class="btn danger" type="button" data-action="delete-route" data-place="${esc(place.id)}" data-route="${esc(route.id)}">${icon('trash-2')} Slet</button>`:''}</div></form></div>`;refreshIcons();setTimeout(()=>renderRoutePreview(place,ui.routeDraft),20);}
function renderRoutePreview(place,route){const places=CampingMaps.validCoords(place)?[place]:[];CampingMaps.createMap('routeEditorMap',{places,route:route.coordinates?.length?route:null,style:data.settings.mapStyle,provider:'maplibre',fullscreen:false,padding:70,maxZoom:13});}

function renderRouteDetail(place,route){app.innerHTML=`<div class="page">${pageHeader(route.name,`${place.name} · ${route.difficulty||'Sværhedsgrad ikke angivet'}`,'bike',`<a class="btn" href="#/rute-editor/${encodeURIComponent(place.id)}/${encodeURIComponent(route.id)}">${icon('pencil')} Redigér</a><button class="btn primary" data-action="share-route" data-place="${esc(place.id)}" data-route="${esc(route.id)}">${icon('share-2')} Del</button>`)}<section class="route-stats"><article class="route-stat card"><strong>${route.distance?formatKm(route.distance):'–'}</strong><span>Afstand</span></article><article class="route-stat card"><strong>${route.duration?formatDuration(route.duration):'–'}</strong><span>Varighed</span></article><article class="route-stat card"><strong>${esc(route.difficulty||'–')}</strong><span>Sværhedsgrad</span></article><article class="route-stat card"><strong>${(route.waypoints?.length||Math.max(0,(route.coordinates?.length||0)-2))}</strong><span>Mellempunkter</span></article></section><section class="section-card card mt-2"><div id="routeDetailMap" class="route-detail-map"></div></section><section class="detail-grid mt-2"><article class="section-card card"><h2 class="mt-0">Rutebeskrivelse</h2><p>${nl2br(route.description||'Ingen beskrivelse endnu.')}</p><div class="divider"></div><p><strong>Start:</strong> ${esc(route.start||place.name)}</p><p><strong>Slut:</strong> ${esc(route.end||'Ikke angivet')}</p></article><aside class="section-card card"><h2 class="mt-0">Åbn eller del</h2><div class="header-actions" style="justify-content:flex-start">${route.googleMapsLink?`<a class="btn" target="_blank" rel="noopener" href="${esc(route.googleMapsLink)}">${icon('map')} Google Maps</a>`:''}<button class="btn" data-action="copy-route-link" data-place="${esc(place.id)}" data-route="${esc(route.id)}">${icon('copy')} Kopiér link</button></div></aside></section></div>`;refreshIcons();setTimeout(()=>CampingMaps.createMap('routeDetailMap',{places:[],route,style:data.settings.mapStyle,provider:'maplibre',fullscreen:true,padding:70,maxZoom:14}),20);}

function renderRatingCategories(){app.innerHTML=`<div class="page form-page">${pageHeader('Vurderingskategorier','Tilpas de kategorier I bruger, når campingpladserne bedømmes','star',`<a class="btn" href="#/indstillinger">${icon('arrow-left')} Indstillinger</a>`)}<form id="categoriesForm"><section class="form-section card"><div id="categoryEditor" class="array-list">${data.ratingCategories.map(cat=>categoryRow(cat)).join('')}</div><button class="btn mt-2" type="button" data-action="add-category">${icon('plus')} Tilføj kategori</button></section><div class="sticky-actions"><button class="btn" type="button" data-action="restore-categories">Gendan standard</button><button class="btn primary" type="submit">${icon('save')} Gem kategorier</button></div></form></div>`;refreshIcons();}
function categoryRow(cat={id:uid('category'),name:'Ny kategori',icon:'star'}){return `<div class="array-row category-editor-row" data-id="${esc(cat.id)}"><input class="form-control" data-field="name" value="${esc(cat.name)}" placeholder="Kategorinavn"><select class="form-control" data-field="icon">${['star','map-pin','badge-dollar-sign','sparkles','bell','shower-head','paw-print','bike','trees','waves','sun','heart'].map(v=>`<option value="${v}" ${cat.icon===v?'selected':''}>${v}</option>`).join('')}</select><button type="button" class="btn small danger" data-action="remove-category">${icon('trash-2')}</button></div>`;}

function renderBackup(){app.innerHTML=`<div class="page form-page">${pageHeader('Sikkerhedskopi','Eksportér, importér og flyt data mellem enheder','database-backup',`<a class="btn" href="#/indstillinger">${icon('arrow-left')} Indstillinger</a>`)}<section class="form-section card"><h2>Eksportér alle campingdata</h2><p>Backupfilen indeholder campingpladser, billeder, vurderinger, seværdigheder, cykelruter og indstillinger. API-nøgler fjernes automatisk.</p><button class="btn primary" data-action="export-backup">${icon('download')} Hent JSON-backup</button></section><section class="form-section card"><h2>Importér tidligere sikkerhedskopi</h2><p>Import erstatter de nuværende data. Tag eventuelt en ny backup først.</p><button class="btn" data-action="import-backup">${icon('upload')} Vælg backupfil</button></section><section class="form-section card"><h2>Status</h2><p><strong>${data.places.length}</strong> campingpladser · <strong>${routesCount()}</strong> cykelruter · senest gemt ${formatDate(data.updatedAt?.slice(0,10))}</p></section></div>`;refreshIcons();}

function renderImageModal(place,index){const src=place.images?.[index];if(!src)return;$('#modalRoot').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal" style="width:min(1000px,100%)" onclick="event.stopPropagation()"><header class="modal-header"><h2>${esc(place.name)} · billede ${index+1}</h2><button class="icon-button" data-action="close-modal">${icon('x')}</button></header><div class="modal-body"><img src="${esc(src)}" alt="${esc(place.name)}" style="width:100%;max-height:72vh;object-fit:contain;border-radius:12px"></div></section></div>`;refreshIcons();}

async function compressImage(file,maxSize=1600,quality=.78){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{let {width,height}=img;const scale=Math.min(1,maxSize/Math.max(width,height));width=Math.round(width*scale);height=Math.round(height*scale);const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;canvas.getContext('2d').drawImage(img,0,0,width,height);resolve(canvas.toDataURL('image/jpeg',quality));};img.src=reader.result;};reader.readAsDataURL(file);});}

function exportBackup(){const copy=structuredClone(data);copy.settings.orsKey='';copy.settings.googleMapsKey='';copy.exportedAt=new Date().toISOString();const blob=new Blob([JSON.stringify(copy,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`vores-camping-backup-${isoDate()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backupfilen er hentet. API-nøglerne blev ikke taget med.');}
function importBackupFile(file){const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result);confirmModal('Importér sikkerhedskopi','De nuværende campingdata erstattes af indholdet i backupfilen.',()=>{const oldKeys={orsKey:data.settings.orsKey,googleMapsKey:data.settings.googleMapsKey};data=migrate(parsed);data.settings.orsKey=oldKeys.orsKey;data.settings.googleMapsKey=oldKeys.googleMapsKey;saveData('Sikkerhedskopien er importeret.');location.hash='#/overblik';},{danger:false,confirmText:'Importér'});}catch(err){toast('Filen er ikke en gyldig Vores Camping-backup.','error');}};reader.readAsText(file);}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Linket er kopieret.');}catch(_e){const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();toast('Linket er kopieret.');}}
async function shareContent(payload){if(navigator.share){try{await navigator.share(payload);return;}catch(err){if(err.name==='AbortError')return;}}await copyText(payload.url||payload.text||'');}

function openGenericSearch(){location.hash='#/kort';setTimeout(()=>$('#mapOnlineSearch')?.focus(),120);}
async function searchForForm(){const query=$('#formPlaceSearch')?.value.trim();if(!query)return toast('Skriv et navn eller område først.','warn');toast('Søger efter campingpladsen…');try{ui.formSearchResults=await CampingMaps.geocode(query,data.settings.orsKey,{limit:8});const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal" onclick="event.stopPropagation()"><header class="modal-header"><h2>Vælg søgeresultat</h2><button class="icon-button" data-action="close-modal">${icon('x')}</button></header><div class="modal-body"><div class="array-list">${ui.formSearchResults.map((r,i)=>`<button class="search-result" type="button" data-action="use-form-result" data-index="${i}" style="border:0;width:100%;text-align:left;background:transparent"><div><h4>${esc(r.name)}</h4><p>${esc(r.label)}</p></div>${icon('chevron-right')}</button>`).join('')||'<p>Ingen resultater fundet.</p>'}</div></div></section></div>`;refreshIcons();}catch(err){toast(err.message||'Søgningen fejlede.','error');}}
function applyFormSearchResult(result){const form=$('#placeForm');if(!form)return;const set=(name,value)=>{const el=form.elements[name];if(el&&value!==undefined&&value!==null)el.value=value;};set('name',result.name);set('address',result.address);set('postalCode',result.postalCode);set('city',result.city);set('region',result.region);set('country',result.country);set('lat',result.coords?.lat);set('lng',result.coords?.lng);$('#formPlaceSearch').value=result.name;closeModal();toast('Oplysningerne er overført til formularen.');}

function collectPlaceForm(form){const fd=new FormData(form);const placeId=form.dataset.id;const existing=getPlace(placeId)||blankPlace(fd.get('status'));const status=fd.get('status')||'visited';const visitDates=$$('.visit-date-row input[type="date"]',form).map(i=>i.value).filter(Boolean).sort();const sights=$$('.sight-editor-row',form).map(row=>({id:row.dataset.id||uid('sight'),name:$('[data-field="name"]',row)?.value.trim()||'',description:$('[data-field="description"]',row)?.value.trim()||'',link:$('[data-field="link"]',row)?.value.trim()||''})).filter(s=>s.name||s.description||s.link);const ratings={};data.ratingCategories.forEach(cat=>ratings[cat.id]=num(fd.get(`rating_${cat.id}`),0));return {...existing,id:placeId,status,name:String(fd.get('name')||'').trim(),address:String(fd.get('address')||'').trim(),postalCode:String(fd.get('postalCode')||'').trim(),city:String(fd.get('city')||'').trim(),region:String(fd.get('region')||'').trim(),country:String(fd.get('country')||'').trim(),website:String(fd.get('website')||'').trim(),phone:String(fd.get('phone')||'').trim(),coords:{lat:num(fd.get('lat'),NaN),lng:num(fd.get('lng'),NaN)},visitDates,plannedDate:String(fd.get('plannedDate')||''),description:String(fd.get('description')||'').trim(),notes:String(fd.get('notes')||'').trim(),tags:String(fd.get('tags')||'').split(',').map(s=>s.trim()).filter(Boolean),ratings,images:[...ui.editingImages],sights,updatedAt:new Date().toISOString()};}
function savePlaceForm(form,viewAfter=false){const place=collectPlaceForm(form);if(!place.name)return toast('Campingpladsen skal have et navn.','warn');const isNew=form.dataset.new==='true';const index=data.places.findIndex(p=>p.id===place.id);if(index>=0)data.places[index]=place;else data.places.push(place);saveData(isNew?'Campingpladsen er tilføjet.':'Campingpladsen er gemt.');location.hash=viewAfter?`#/campingplads/${encodeURIComponent(place.id)}`:(place.status==='wishlist'?'#/oenskeliste':'#/besoegte');}

async function findMissingCoords(){const missing=data.places.filter(p=>!CampingMaps.validCoords(p));if(!missing.length)return toast('Alle campingpladser har allerede koordinater.');if(!data.settings.orsKey)toast('Openrouteservice-nøglen mangler. Den gratis reserve forsøges.','warn');let found=0;for(const place of missing){try{const q=[place.name,place.address,place.city,place.country].filter(Boolean).join(', ');const result=(await CampingMaps.geocode(q,data.settings.orsKey,{limit:1}))[0];if(result?.coords){place.coords=result.coords;found++;}}catch(err){console.warn(err);}}saveData(`${found} af ${missing.length} manglende koordinater blev fundet.`);renderMap();}

function settingsFromForm(form){const fd=new FormData(form);data.settings={...data.settings,appName:String(fd.get('appName')||'Vores Camping'),subtitle:String(fd.get('subtitle')||''),names:String(fd.get('names')||''),greetingText:String(fd.get('greetingText')||''),nextTrip:{title:String(fd.get('tripTitle')||''),date:String(fd.get('tripDate')||'')},showCountdown:fd.get('showCountdown')==='on',scale:num(fd.get('scale'),1),theme:String(fd.get('theme')||'light'),accent:String(fd.get('accent')||'#1f3d2e'),density:String(fd.get('density')||'compact'),mapProvider:String(fd.get('mapProvider')||'maplibre'),mapStyle:String(fd.get('mapStyle')||'liberty'),orsKey:String(fd.get('orsKey')||'').trim(),googleMapsKey:String(fd.get('googleMapsKey')||'').trim()};}

let inputTimer;
document.addEventListener('input',event=>{
 const t=event.target;
 if(t.id==='visitedSearch'){ui.visitedSearch=t.value;clearTimeout(inputTimer);inputTimer=setTimeout(renderVisited,160);}
 if(t.id==='wishSearch'){ui.wishSearch=t.value;clearTimeout(inputTimer);inputTimer=setTimeout(renderWishlist,160);}
 if(t.id==='mapStoredSearch'){ui.mapStoredSearch=t.value;clearTimeout(inputTimer);inputTimer=setTimeout(renderMap,180);}
 if(t.id==='scaleInput'){const val=num(t.value,1);$('#scaleValue').textContent=`${Math.round(val*100)} %`;document.documentElement.style.setProperty('--scale',String(val));}
});

document.addEventListener('change',async event=>{
 const t=event.target;
 if(t.id==='wishSort'){ui.wishSort=t.value;renderWishlist();}
 if(t.id==='placeImages'){
  const files=[...t.files];if(!files.length)return;toast(`Komprimerer ${files.length} billede${files.length===1?'':'r'}…`);
  for(const file of files){try{ui.editingImages.push(await compressImage(file));}catch(err){toast(`Kunne ikke læse ${file.name}.`,'error');}}
  $('#imagePreviewGrid').innerHTML=renderImagePreviews();t.value='';
 }
 if(t.id==='coverUpload'&&t.files?.[0]){try{data.settings.coverImage=await compressImage(t.files[0],1800,.82);saveData('Coverbilledet er opdateret.');renderSettings();}catch(_e){toast('Coverbilledet kunne ikke læses.','error');}}
 if(t.id==='hiddenImport'&&t.files?.[0]){importBackupFile(t.files[0]);t.value='';}
});

document.addEventListener('submit',async event=>{
 event.preventDefault();const form=event.target;
 if(form.id==='settingsForm'){settingsFromForm(form);saveData('Indstillingerne er gemt.');renderSettings();return;}
 if(form.id==='placeForm'){savePlaceForm(form,false);return;}
 if(form.id==='categoriesForm'){const rows=$$('.category-editor-row',form);const categories=rows.map(row=>({id:row.dataset.id||uid('category'),name:$('[data-field="name"]',row).value.trim(),icon:$('[data-field="icon"]',row).value})).filter(c=>c.name);if(!categories.length)return toast('Der skal være mindst én vurderingskategori.','warn');data.ratingCategories=categories;saveData('Vurderingskategorierne er gemt.');location.hash='#/indstillinger';return;}
 if(form.id==='routeForm'){
  const fd=new FormData(form),place=getPlace(form.dataset.place);if(!place)return;const start=parseCoordPair(fd.get('startCoords')),end=parseCoordPair(fd.get('endCoords'));const waypointPairs=String(fd.get('waypointCoords')||'').split('\n').map(parseCoordPair).filter(Boolean);const basicCoords=[start,...waypointPairs,end].filter(Boolean).map(c=>[c.lng,c.lat]);const route={...(ui.routeDraft||{}),id:form.dataset.route,name:String(fd.get('name')||'').trim(),start:String(fd.get('start')||''),end:String(fd.get('end')||''),difficulty:String(fd.get('difficulty')||'Let'),description:String(fd.get('description')||''),googleMapsLink:String(fd.get('googleMapsLink')||''),waypoints:waypointPairs,coordinates:ui.routeDraft?.coordinates?.length?ui.routeDraft.coordinates:basicCoords,updatedAt:new Date().toISOString()};if(!route.name)return toast('Ruten skal have et navn.','warn');const idx=(place.routes||[]).findIndex(r=>r.id===route.id);if(idx>=0)place.routes[idx]=route;else(place.routes||(place.routes=[])).push(route);saveData('Cykelruten er gemt.');location.hash=`#/rute/${encodeURIComponent(place.id)}/${encodeURIComponent(route.id)}`;return;
 }
 if(form.id==='mapSearchForm'){
  const q=$('#mapOnlineSearch').value.trim();if(!q)return toast('Skriv et navn, en by eller et område.','warn');const submit=form.querySelector('button[type="submit"]');submit.disabled=true;submit.textContent='Søger…';try{ui.mapResults=await CampingMaps.geocode(q,data.settings.orsKey,{limit:10});if(!ui.mapResults.length)toast('Ingen campingpladser blev fundet.','warn');renderMap();}catch(err){toast(err.message||'Onlinesøgningen fejlede.','error');submit.disabled=false;submit.textContent='Søg';}return;
 }
});

document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
 if(action==='close-modal'){closeModal();return;}
 if(action==='reload-app'){route();return;}
 if(action==='quick-add'){location.hash='#/tilfoej?status=visited';return;}
 if(action==='open-search'){openGenericSearch();return;}
 if(action==='visited-sort'){ui.visitedSort=el.dataset.sort;renderVisited();return;}
 if(action==='map-filter'){ui.mapFilter=el.dataset.filter;renderMap();return;}
 if(action==='toggle-favorite'){const p=getPlace(el.dataset.id);if(p){p.favorite=!p.favorite;saveData(p.favorite?'Tilføjet som favorit.':'Fjernet fra favoritter.');route();}return;}
 if(action==='mark-visited'){const p=getPlace(el.dataset.id);if(p){p.status='visited';p.plannedDate='';if(!p.visitDates?.length)p.visitDates=[isoDate()];saveData(`${p.name} er nu markeret som besøgt.`);location.hash=`#/campingplads/${encodeURIComponent(p.id)}`;}return;}
 if(action==='delete-place'){const p=getPlace(el.dataset.id);if(p)confirmModal('Slet campingplads',`Vil du slette ${p.name} og alle tilknyttede billeder, vurderinger og ruter?`,()=>{data.places=data.places.filter(x=>x.id!==p.id);saveData('Campingpladsen er slettet.');location.hash=p.status==='wishlist'?'#/oenskeliste':'#/besoegte';});return;}
 if(action==='save-and-view'){const form=$('#placeForm');if(form)savePlaceForm(form,true);return;}
 if(action==='set-rating'){const box=el.closest('.star-input'),value=num(el.dataset.value);$('input[type="hidden"]',box).value=value;$$('button',box).forEach((b,i)=>b.classList.toggle('on',i<value));return;}
 if(action==='remove-image'){ui.editingImages.splice(Number(el.dataset.index),1);$('#imagePreviewGrid').innerHTML=renderImagePreviews();return;}
 if(action==='add-visit-date'){$('#visitDatesList').insertAdjacentHTML('beforeend',`<div class="array-row visit-date-row"><input class="form-control" type="date" value="${isoDate()}"><span></span><button type="button" class="btn small danger" data-action="remove-array-row">${icon('trash-2')}</button></div>`);refreshIcons();return;}
 if(action==='add-sight'){$('#sightsEditor').insertAdjacentHTML('beforeend',`<div class="array-row sight-editor-row"><input class="form-control" data-field="name" placeholder="Navn"><input class="form-control" data-field="description" placeholder="Beskrivelse"><button type="button" class="btn small danger" data-action="remove-array-row">${icon('trash-2')}</button><input class="form-control" data-field="link" placeholder="Link til placering (valgfrit)" style="grid-column:1/-1"></div>`);refreshIcons();return;}
 if(action==='remove-array-row'){el.closest('.array-row')?.remove();return;}
 if(action==='search-place-form'){await searchForForm();return;}
 if(action==='use-form-result'){applyFormSearchResult(ui.formSearchResults?.[Number(el.dataset.index)]);return;}
 if(action==='use-current-location'){try{const pos=await CampingMaps.currentPosition();const form=$('#placeForm');form.elements.lat.value=pos.lat.toFixed(6);form.elements.lng.value=pos.lng.toFixed(6);toast('Den aktuelle placering er indsat.');}catch(err){toast(err.message,'error');}return;}
 if(action==='preview-form-map'){const form=$('#placeForm'),lat=num(form.elements.lat.value,NaN),lng=num(form.elements.lng.value,NaN);if(!Number.isFinite(lat)||!Number.isFinite(lng))return toast('Indtast gyldige koordinater først.','warn');const box=$('#formMapPreview');box.hidden=false;setTimeout(()=>CampingMaps.createMap('formMapPreview',{places:[{id:'preview',name:form.elements.name.value||'Valgt placering',status:form.elements.status.value,city:form.elements.city.value,country:form.elements.country.value,coords:{lat,lng},images:ui.editingImages}],style:data.settings.mapStyle,fullscreen:false,padding:80,maxZoom:14}),20);return;}
 if(action==='delete-route'){const p=getPlace(el.dataset.place),r=p?.routes?.find(x=>x.id===el.dataset.route);if(p&&r)confirmModal('Slet cykelrute',`Vil du slette ruten “${r.name}”?`,()=>{p.routes=p.routes.filter(x=>x.id!==r.id);saveData('Cykelruten er slettet.');location.hash=`#/campingplads/${encodeURIComponent(p.id)}`;});return;}
 if(action==='calculate-route'){const form=$('#routeForm'),start=parseCoordPair(form.elements.startCoords.value),end=parseCoordPair(form.elements.endCoords.value),waypoints=form.elements.waypointCoords.value.split('\n').map(parseCoordPair).filter(Boolean);if(!start||!end)return toast('Start- og slutkoordinater skal udfyldes som lat, lng.','warn');el.disabled=true;el.innerHTML='Beregner…';try{const calculated=await CampingMaps.calculateRoute([start,...waypoints,end].map(c=>[c.lng,c.lat]),data.settings.orsKey);ui.routeDraft={...(ui.routeDraft||{}),...calculated,waypoints};$('#routeSummary').textContent=`${formatKm(calculated.distance)} · ${formatDuration(calculated.duration)}`;renderRoutePreview(getPlace(form.dataset.place),ui.routeDraft);toast('Ruten er beregnet.');}catch(err){toast(err.message,'error');}finally{el.disabled=false;el.innerHTML=`${icon('route')} Beregn med Openrouteservice`;refreshIcons();}return;}
 if(action==='route-use-place'){const form=$('#routeForm'),p=getPlace(form.dataset.place);if(CampingMaps.validCoords(p)){form.elements.startCoords.value=`${p.coords.lat}, ${p.coords.lng}`;form.elements.start.value=p.name;toast('Campingpladsen er valgt som start.');}else toast('Campingpladsen mangler koordinater.','warn');return;}
 if(action==='open-image'){const p=getPlace(el.dataset.place);if(p)renderImageModal(p,Number(el.dataset.index));return;}
 if(action==='share-place'){const p=getPlace(el.dataset.id);if(p)shareContent({title:p.name,text:`${p.name} – ${[p.city,p.country].filter(Boolean).join(', ')}`,url:CampingMaps.validCoords(p)?`https://www.google.com/maps/search/?api=1&query=${p.coords.lat},${p.coords.lng}`:location.href});return;}
 if(action==='share-route'||action==='copy-route-link'){const p=getPlace(el.dataset.place),r=p?.routes?.find(x=>x.id===el.dataset.route);if(r){const url=r.googleMapsLink||location.href;if(action==='share-route')shareContent({title:r.name,text:`${r.name} – ${p.name}`,url});else copyText(url);}return;}
 if(action==='theme-choice'){const form=$('#settingsForm');form.elements.theme.value=el.dataset.theme;$$('[data-action="theme-choice"]').forEach(b=>b.classList.toggle('active',b===el));document.body.classList.toggle('theme-dark',el.dataset.theme==='dark');return;}
 if(action==='density-choice'){const form=$('#settingsForm');form.elements.density.value=el.dataset.density;$$('[data-action="density-choice"]').forEach(b=>b.classList.toggle('active',b===el));document.body.classList.toggle('density-airy',el.dataset.density==='airy');return;}
 if(action==='accent-choice'){const form=$('#settingsForm');form.elements.accent.value=el.dataset.color;document.documentElement.style.setProperty('--forest',el.dataset.color);$$('[data-action="accent-choice"]').forEach(b=>b.classList.toggle('active',b===el));return;}
 if(action==='section-toggle'){const id=el.dataset.section;const hidden=new Set(data.settings.hiddenSections||[]);el.checked?hidden.delete(id):hidden.add(id);data.settings.hiddenSections=[...hidden];return;}
 if(action==='section-move'){const arr=data.settings.sections||[],idx=arr.indexOf(el.dataset.section),next=el.dataset.direction==='up'?idx-1:idx+1;if(idx>=0&&next>=0&&next<arr.length){[arr[idx],arr[next]]=[arr[next],arr[idx]];data.settings.sections=arr;renderSettings();}return;}
 if(action==='test-api'){el.disabled=true;el.textContent='Tester…';try{const style=CampingMaps.styles[data.settings.mapStyle]||CampingMaps.styles.liberty;const mapResponse=await fetch(style);if(!mapResponse.ok)throw new Error('Korttjenesten svarede ikke.');const key=$('#settingsForm')?.elements.orsKey.value.trim();if(key){const res=await CampingMaps.geocode('Holstebro, Danmark',key,{limit:1});if(!res.length)throw new Error('Openrouteservice gav intet resultat.');toast('Kort og Openrouteservice virker.');}else toast('OpenFreeMap virker. ORS-nøglen er ikke udfyldt.','warn');}catch(err){toast(err.message||'Forbindelsen kunne ikke testes.','error');}finally{el.disabled=false;el.innerHTML=`${icon('plug-zap')} Test forbindelse`;refreshIcons();}return;}
 if(action==='export-backup'){exportBackup();return;}
 if(action==='import-backup'){$('#hiddenImport').click();return;}
 if(action==='reset-data'){confirmModal('Nulstil alle campingdata','Alle campingpladser, billeder, vurderinger, ruter og indstillinger slettes og erstattes af appens eksempeldata.',()=>{data=defaultData();saveData('Appen er nulstillet.');location.hash='#/overblik';});return;}
 if(action==='add-category'){$('#categoryEditor').insertAdjacentHTML('beforeend',categoryRow());refreshIcons();return;}
 if(action==='remove-category'){el.closest('.category-editor-row')?.remove();return;}
 if(action==='restore-categories'){confirmModal('Gendan standardkategorier','De nuværende kategorier erstattes af standardkategorierne.',()=>{data.ratingCategories=structuredClone(DEFAULT_CATEGORIES);renderRatingCategories();},{danger:false,confirmText:'Gendan'});return;}
 if(action==='find-missing-coords'){await findMissingCoords();return;}
 if(action==='show-location'){try{ui.userLocation=await CampingMaps.currentPosition();toast(`Placering fundet med ca. ${Math.round(ui.userLocation.accuracy||0)} meters nøjagtighed.`);renderMap();}catch(err){toast(err.message,'error');}return;}
 if(action==='add-search-result'){const r=ui.mapResults[Number(el.dataset.index)];if(!r)return;const p=blankPlace(el.dataset.status);Object.assign(p,{name:r.name,address:r.address,postalCode:r.postalCode,city:r.city,region:r.region,country:r.country,coords:r.coords});data.places.push(p);saveData('Søgeresultatet er tilføjet.');location.hash=`#/rediger/${encodeURIComponent(p.id)}`;return;}
});

function route(){
 try{
  clearInterval(countdownTimer);CampingMaps?.destroyAll?.();applyDerived();updateShell();const r=parseRoute();setActiveNav(r.path);
  if(r.path==='overblik')renderOverview();
  else if(r.path==='besoegte')renderVisited();
  else if(r.path==='kort')renderMap();
  else if(r.path==='bedst')renderBest();
  else if(r.path==='oenskeliste')renderWishlist();
  else if(r.path==='indstillinger')renderSettings();
  else if(r.path==='tilfoej'){const p=blankPlace(r.query.get('status')==='wishlist'?'wishlist':'visited');renderPlaceEditor(p,true);}
  else if(r.path==='rediger'){const p=getPlace(decodeURIComponent(r.segments[1]||''));p?renderPlaceEditor(p,false):notFound();}
  else if(r.path==='campingplads'){const p=getPlace(decodeURIComponent(r.segments[1]||''));p?renderPlaceDetail(p):notFound();}
  else if(r.path==='rute-editor'){const p=getPlace(decodeURIComponent(r.segments[1]||''));p?renderRouteEditor(p,decodeURIComponent(r.segments[2]||'ny')):notFound();}
  else if(r.path==='rute'){const p=getPlace(decodeURIComponent(r.segments[1]||''));const rt=p?.routes?.find(x=>x.id===decodeURIComponent(r.segments[2]||''));p&&rt?renderRouteDetail(p,rt):notFound();}
  else if(r.path==='vurderingskategorier')renderRatingCategories();
  else if(r.path==='backup')renderBackup();
  else notFound();
  app.focus({preventScroll:true});
 }catch(err){errorView(err);}
}
function notFound(){app.innerHTML=`<section class="page empty-state card"><div class="empty-icon">${icon('map-pin-off')}</div><h1>Siden blev ikke fundet</h1><p>Den campingplads er vist kørt videre uden at efterlade koordinater.</p><a class="btn primary" href="#/overblik">Tilbage til overblik</a></section>`;refreshIcons();}

async function cleanupOldCaches(){
 try{const appBase=new URL('./',location.href).href;if('serviceWorker'in navigator){const regs=await navigator.serviceWorker.getRegistrations();await Promise.all(regs.filter(r=>r.scope.startsWith(appBase)||appBase.startsWith(r.scope)).map(r=>r.unregister()));}if('caches'in window){const keys=await caches.keys();await Promise.all(keys.filter(k=>/vores[-_ ]?camping/i.test(k)).map(k=>caches.delete(k)));}}catch(err){console.warn('Cacheoprydning',err);}
}
function networkStatus(){const banner=$('#offlineBanner');banner.hidden=navigator.onLine;}

function init(){
 data=loadData();applyDerived();saveData();applySettings();updateShell();networkStatus();cleanupOldCaches();
 window.addEventListener('hashchange',route);window.addEventListener('online',networkStatus);window.addEventListener('offline',networkStatus);window.addEventListener('camping-libs-ready',()=>{refreshIcons();const p=parseRoute().path;if(window.maplibregl&&['overblik','kort','campingplads','rute','rute-editor'].includes(p))route();});
 if(!location.hash)location.hash='#/overblik';else route();
 refreshIcons();
}

window.addEventListener('DOMContentLoaded',init);
})();
